def VTask.prev {α : Type u_1} [DecidableEq α] (l : List α) (x : α) (h : x ∈ l) : α :=
  let h_nonempty : l ≠ [] :=
    show l ≠ [] by
      intro hnil
      exact (List.mem_nil_iff _).1 hnil x h
  let initial_prev : α := l.getLast h_nonempty
  let rec helper (prev : α) (remaining : List α) (h_remaining : x ∈ remaining) : α :=
    match remaining with
    | [] => absurd h_remaining (by simp)
    | hd :: tl =>
      if h_eq : hd == x then prev else helper hd tl (List.mem_tail h_remaining h_eq)
  helper initial_prev l h
